func scoreValue(sc store.Score) string {
	switch sc.DataType {
	case store.ScoreBoolean:
		if sc.ValueNum != nil && *sc.ValueNum == 1 {
			return "true"
		}
		return "false"
	case store.ScoreCategorical:
		if sc.ValueNum != nil {
			return fmt.Sprintf("%s (%.2f)", sc.ValueStr, *sc.ValueNum)
		}
		return sc.ValueStr
	}
	if sc.ValueNum == nil {
		return "-"
	}
	return fmt.Sprintf("%.4g", *sc.ValueNum)
}

